ng): AgentConversationMessageEntry {\\\\\\\\\\\\\\\\n    return { content, id, kind: 'message', role: 'assistant', timestamp: '2026-07-27T10:00:00.000Z' }\\\\\\\\\\\\\\\\n}\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nfunction eventEntry(event: AgentConversationEvent): AgentConversationEventEntry {\\\\\\\\\\\\\\\\n    return { ...event, kind: 'event' }\\\\\\\\\\\\\\\\n}\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nfunction conversation(\\\\\\\\\\\\\\\\n    path: string,\\\\\\\\\\\\\\\\n    entries: AgentConversationEntry[],\\\\\\\\\\\\\\\\n    agent: string | null = null,\\\\\\\\\\\\\\\\n): AgentConversation {\\\\\\\\\\\\\\\\n    return {\\\\\\\\\\\\\\\\n        actionId: 'review',\\\\\\\\\\\\\\\\n        cardInternalId: 'card-1',\\\\\\\\\\\\\\\\n        cardPath: 'design/F-83.md',\\\\\\\\\\\\\\\\n        completedAt: '2026-07-27T10:01:00.000Z',\\\\\\\\\\\\\\\\n        entries,\\\\\\\\\\\\\\\\n        hasExplicitTitle: true,\\\\\\\\\\\\\\\\n        id: path,\\\\\\\\\\\\\\\\n        path,\\\\\\\\\\\\\\\\n        providerSessions: agent ? [{\\\\\\\\\\\\\\\\n            agent,\\\\\\\\\\\\\\\\n            conversationId: 'provider-1',\\\\\\\\\\\\\\\\n            createdAt: '2026-07-27T10:00:00.000Z',\\\\\\\\\\\\\\\\n            lastUsedAt: '2026-07-27T10:01:00.000Z',\\\\\\\\\\\\\\\\n            synchronizedThroughMessageId: entries.findLast((entry) => entry.kind === 'message')?.id ?? '',\\\\\\\\\\\\\\\\n        }] : [],\\\\\\\\\\\\\\\\n        startedAt: '2026-07-27T10:00:00.000Z',\\\\\\\\\\\\\\\\n        status: 'completed',\\\\\\\\\\\\\\\\n        title: path,\\\\\\\\\\\\\\\\n    }\\\\\\\\\\\\\\\\n}\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nfunction renderChat(value: AgentConversation | null) {\\\\\\\\\\\\\\\\n    return render(\\\\\\\\\\\\\\\\n        <AppThemeProvider>\\\\\\\\\\\\\\\\n            <ActionConversationChat conversation={value} status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"idle\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" />\\\\\\\\\\\\\\\\n        </AppThemeProvider>,\\\\\\\\\\\\\\\\n    )\\\\\\\\\\\\\\\\n}\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nfunction MarkdownContentSxOverride({ children }: { children: ReactNode }) {\\\\\\\\\\\\\\\\n    const theme = useAppTheme()\\\\\\\\\\\\\\\\n    const value = { ...theme, markdownContentSx: { paddingTop: '37px' } }\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    return <AppThemeContext.Provider value={value}>{children}</AppThemeContext.Provider>\\\\\\\\\\\\\\\\n}\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nfunction restoreProperty(name: 'clientHeight' | 'scrollHeight' | 'scrollTop', descriptor?: PropertyDescriptor) {\\\\\\\\\\\\\\\\n    if (descriptor) {\\\\\\\\\\\\\\\\n        Object.defineProperty(HTMLElement.prototype, name, descriptor)\\\\\\\\\\\\\\\\n        return\\\\\\\\\\\\\\\\n    }\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    delete HTMLElement.prototype[name]\\\\\\\\\\\\\\\\n}\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndescribe('ActionConversationChat', () => {\\\\\\\\\\\\\\\\n    beforeEach(() => {\\\\\\\\\\\\\\\\n        clientHeight = 100\\\\\\\\\\\\\\\\n        scrollHeight = 300\\\\\\\\\\\\\\\\n        scrollPositions = new WeakMap<HTMLElement, number>()\\\\\\\\\\\\\\\\n        Object.defineProperty(HTMLElement.prototype, 'clientHeight', { configurable: true, get: () => clientHeight })\\\\\\\\\\\\\\\\n        Object.defineProperty(HTMLElement.prototype, 'scrollHeight', { configurable: true, get: () => scrollHeight })\\\\\\\\\\\\\\\\n        Object.defineProperty(HTMLElement.prototype, 'scrollTop', {\\\\\\\\\\\\\\\\n            configurable: true,\\\\\\\\\\\\\\\\n            get() {\\\\\\\\\\\\\\\\n                return scrollPositions.get(this) ?? 0\\\\\\\\\\\\\\\\n            },\\\\\\\\\\\\\\\\n            set(value: number) {\\\\\\\\\\\\\\\\n                const maximumScrollTop = Math.max(0, scrollHeight - clientHeight)\\\\\\\\\\\\\\\\n                scrollPositions.set(this, Math.max(0, Math.min(value, maximumScrollTop)))\\\\\\\\\\\\\\\\n            },\\\\\\\\\\\\\\\\n        })\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    afterEach(() => {\\\\\\\\\\\\\\\\n        cleanup()\\\\\\\\\\\\\\\\n        vi.restoreAllMocks()\\\\\\\\\\\\\\\\n        restoreProperty('clientHeight', originalClientHeight)\\\\\\\\\\\\\\\\n        restoreProperty('scrollHeight', originalScrollHeight)\\\\\\\\\\\\\\\\n        restoreProperty('scrollTop', originalScrollTop)\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    it('starts at the end when a conversation loads', () => {\\\\\\\\\\\\\\\\n        renderChat(conversation('first.json', [message('message-1', 'First')]))\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        expect(screen.getByLabelText('Conversation chat').scrollTop).toBe(200)\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    it('marks active conversation viewed when it completes while displayed', async () => {\\\\\\\\\\\\\\\\n        const onConversationViewed = vi.fn()\\\\\\\\\\\\\\\\n        const completedConversation = conversation('active.json', [message('message-1', 'Done')])\\\\\\\\\\\\\\\\n        const runningConversation = { ...completedConversation, completedAt: null, status: 'running' as const }\\\\\\\\\\\\\\\\n        const { rerender } = render(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <ActionConversationChat\\\\\\\\\\\\\\\\n                    conversation={runningConversation}\\\\\\\\\\\\\\\\n                    onConversationViewed={onConversationViewed}\\\\\\\\\\\\\\\\n                    status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"running\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                />\\\\\\\\\\\\\\\\n            </AppThemeProvider>,\\\\\\\\\\\\\\\\n        )\\\\\\\\\\\\\\\\n        expect(onConversationViewed).not.toHaveBeenCalled()\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        rerender(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <ActionConversationChat\\\\\\\\\\\\\\\\n                    conversation={completedConversation}\\\\\\\\\\\\\\\\n                    onConversationViewed={onConversationViewed}\\\\\\\\\\\\\\\\n                    status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"completed\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                />\\\\\\\\\\\\\\\\n            </AppThemeProvider>,\\\\\\\\\\\\\\\\n        )\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        await waitFor(() => expect(onConversationViewed).toHaveBeenCalledWith(completedConversation))\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    it('uses the derived Markdown style provided by the app theme', () => {\\\\\\\\\\\\\\\\n        render(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <MarkdownContentSxOverride>\\\\\\\\\\\\\\\\n                    <ActionConversationChat\\\\\\\\\\\\\\\\n                        conversation={conversation('styled.json', [message('message-1', 'Styled')])}\\\\\\\\\\\\\\\\n                        status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"idle\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                    />\\\\\\\\\\\\\\\\n                </MarkdownContentSxOverride>\\\\\\\\\\\\\\\\n            </AppThemeProvider>,\\\\\\\\\\\\\\\\n        )\\\\\\\\\\\\\\\\n        const messageBox = screen.getByText('Styled').closest('.mdxeditor-content')?.parentElement\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        expect(messageBox).toHaveStyle({ paddingTop: '37px' })\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    it('returns to the end when the selected conversation changes', () => {\\\\\\\\\\\\\\\\n        const first = conversation('first.json', [message('message-1', 'First')])\\\\\\\\\\\\\\\\n        const second = conversation('second.json', [message('message-2', 'Second')])\\\\\\\\\\\\\\\\n        const { rerender } = renderChat(first)\\\\\\\\\\\\\\\\n        const viewport = screen.getByLabelText('Conversation chat')\\\\\\\\\\\\\\\\n        viewport.scrollTop = 40\\\\\\\\\\\\\\\\n        fireEvent.scroll(viewport)\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        rerender(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <ActionConversationChat conversation={second} status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"idle\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" />\\\\\\\\\\\\\\\\n            </AppThemeProvider>,\\\\\\\\\\\\\\\\n        )\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        expect(viewport.scrollTop).toBe(200)\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    it('keeps new content visible while stuck to the end', () => {\\\\\\\\\\\\\\\\n        const first = conversation('first.json', [message('message-1', 'First')])\\\\\\\\\\\\\\\\n        const grown = conversation('first.json', [message('message-1', 'First'), message('message-2', 'Second')])\\\\\\\\\\\\\\\\n        const { rerender } = renderChat(first)\\\\\\\\\\\\\\\\n        const viewport = screen.getByLabelText('Conversation chat')\\\\\\\\\\\\\\\\n        scrollHeight = 400\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        rerender(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <ActionConversationChat conversation={grown} status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"idle\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" />\\\\\\\\\\\\\\\\n            </AppThemeProvider>,\\\\\\\\\\\\\\\\n        )\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        expect(viewport.scrollTop).toBe(300)\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    it('does not move when new content arrives after the user scrolls up', () => {\\\\\\\\\\\\\\\\n        const first = conversation('first.json', [message('message-1', 'First')])\\\\\\\\\\\\\\\\n        const grown = conversation('first.json', [message('message-1', 'First'), message('message-2', 'Second')])\\\\\\\\\\\\\\\\n        const { rerender } = renderChat(first)\\\\\\\\\\\\\\\\n        const viewport = screen.getByLabelText('Conversation chat')\\\\\\\\\\\\\\\\n        viewport.scrollTop = 40\\\\\\\\\\\\\\\\n        fireEvent.scroll(viewport)\\\\\\\\\\\\\\\\n        scrollHeight = 400\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        rerender(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <ActionConversationChat conversation={grown} status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"idle\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" />\\\\\\\\\\\\\\\\n            </AppThemeProvider>,\\\\\\\\\\\\\\\\n        )\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        expect(viewport.scrollTop).toBe(40)\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    it('restores sticky behavior after the user returns within the end tolerance', () => {\\\\\\\\\\\\\\\\n        const first = conversation('first.json', [message('message-1', 'First')])\\\\\\\\\\\\\\\\n        const grown = conversation('first.json', [message('message-1', 'First'), message('message-2', 'Second')])\\\\\\\\\\\\\\\\n        const { rerender } = renderChat(first)\\\\\\\\\\\\\\\\n        const viewport = screen.getByLabelText('Conversation chat')\\\\\\\\\\\\\\\\n        viewport.scrollTop = 196\\\\\\\\\\\\\\\\n        fireEvent.scroll(viewport)\\\\\\\\\\\\\\\\n        scrollHeight = 400\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        rerender(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <ActionConversationChat conversation={grown} status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"idle\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" />\\\\\\\\\\\\\\\\n            </AppThemeProvider>,\\\\\\\\\\\\\\\\n        )\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        expect(viewport.scrollTop).toBe(300)\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    it('keeps empty content at the end when it is shorter than the viewport', () => {\\\\\\\\\\\\\\\\n        clientHeight = 200\\\\\\\\\\\\\\\\n        scrollHeight = 80\\\\\\\\\\\\\\\\n        const { rerender } = renderChat(null)\\\\\\\\\\\\\\\\n        const viewport = screen.getByLabelText('Conversation chat')\\\\\\\\\\\\\\\\n        fireEvent.scroll(viewport)\\\\\\\\\\\\\\\\n        scrollHeight = 100\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        rerender(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <ActionConversati