ull, status: 'running' as const }\\\\\\\\\\\\\\\\n        const { rerender } = render(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <ActionConversationChat\\\\\\\\\\\\\\\\n                    conversation={runningConversation}\\\\\\\\\\\\\\\\n                    onConversationViewed={onConversationViewed}\\\\\\\\\\\\\\\\n                    status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"running\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                />\\\\\\\\\\\\\\\\n            </AppThemeProvider>,\\\\\\\\\\\\\\\\n        )\\\\\\\\\\\\\\\\n        expect(onConversationViewed).not.toHaveBeenCalled()\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        rerender(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <ActionConversationChat\\\\\\\\\\\\\\\\n                    conversation={completedConversation}\\\\\\\\\\\\\\\\n                    onConversationViewed={onConversationViewed}\\\\\\\\\\\\\\\\n                    status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"completed\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                />\\\\\\\\\\\\\\\\n            </AppThemeProvider>,\\\\\\\\\\\\\\\\n        )\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n        await waitFor(() => expect(onConversationViewed).toHaveBeenCalledWith(completedConversation))\\\\\\\\\\\\\\\\n    })\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n    it('uses the derived Markdown style provided by the app theme', () => {\\\\\\\\\\\\\\\\n        render(\\\\\\\\\\\\\\\\n            <AppThemeProvider>\\\\\\\\\\\\\\\\n                <MarkdownContentSxOverride>\\\\\\\\\\\\\\\\n                    <ActionConversationChat\\\\\\\\\\\\\\\\n                        conversation={conversation('styled.json', [message('message-1', 'Styled')])}\\\\\\\\\\\\\\\\n                        status=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"idle\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                    />\\\\\\\\\\\\\\\\n                </MarkdownContentSxOverride>\\\\\\\\\\\\\\\\n         