} from './agent_acknowledgement_service'
import { hasUnseenConversation, latestUnseenConversation } from './card_agent_state'

const cardInternalId = 'root-card'
const actionId = 'implement'

function conversation(id = 'conversation-1', viewed = true): AgentConversation {
    return {
        actionId,
        cardInternalId,
        cardPath: 'design/F-1-root.md',
        completedAt: null,
        entries: [],
        hasExplicitTitle: true,
        id,
        path: `design/activity/card__root-card.json#conversation=${id}`,
        providerSessions: [],
        startedAt: id === 'newest' ? '2026-01-02T00:00:00.000Z' : '2026-01-01T00:00:00.000Z',
        status: 'running',
        title: 'Agent run',
        viewed,
    }
}

function runEvent(status: ActionRunStatus): ActionRunEvent {
    return {
        actionId,
        context: { cardInternalId, file: 'design/F-1-root.md', kind: 'card' },
        phase: 'main',
        rootActionId: actionId,
        runId: 'run-1',
        status,
        type: 'run',
    }
}

/** Starts the run registry against a bridge that reports the given conversation for the emitted run. */
function startRunRegistry(runConversation: AgentConversation | null) {
    let emit: ((event: ActionRunEvent) => void) | null = null
    const updateActionConversationViewed = vi.fn(async (reference: string, viewed: boolean) => ({
        ...conversation(),
        path: reference,
        viewed,
    }))
    setActionBridgeOverride({
        onActionRun: vi.fn((listener: (event: ActionRunEvent) => void) => {
            emit = listener

            return vi.fn()
        }),
        updateActionConversationViewed,
    } as unknown as ElectronActionBridge)
    actionRunRegistry.start()
    if (!emit) throw new Error('Missing run listener')
    const emitEvent = emit as (event: ActionRunEvent) => void
    let seeded = false
    /** Publishes a status event, seeding the run store with its conversation on first use. */
    const publish = (event: ActionRunEvent) => {
        if (runConversation && !seeded) {
            seeded = true
            emitEvent({ ...event, status: 'running', type: 'run' })
            emitEvent({
                ...event,
                status: 'running',
                type: 'update',
                update: { conversation: runConversation, kind: 'agentStarted' },
            })
        }
        emitEvent(event)
    }

    return { publish, updateActionConversationViewed }
}

describe('AgentAcknowledgementService', () => {
    afterEach(() => {
        actionRunRegistry.stop()
        agentAcknowledgementService.reset()
        agentAcknowledgementService.connectConversationStore(() => null)
        setActionBridgeOverride(null)
        vi.restoreAllMocks()
    })

    it('announces card and exact action events without touching other scopes', async () => {
        const { updateActionConversationViewed } = startRunRegistry(null)
        const exactAction = vi.fn()
        const otherAction = vi.fn()
        const card = vi.fn()
        const otherCard = vi.fn()
        agentAcknowledgementService.addEventListener(actionAcknowledgementEvent(cardInternalId, actionId), exactAction)
        agentAcknowledgementService.addEventListener(actionAcknowledgementEvent(cardInternalId, 'review'), otherAction)
        agentAcknowledgementService.addEventListener(cardAcknowledgementEvent(cardInternalId), card)
        agentAcknowledgementService.addEventListener(cardAcknowledgementEvent('other-card'), otherCard)

        await agentAcknowledgementService.setViewed(cardInternalId, actionId, conversation('conversation-1', false), true)

        expect(updateActionConversationViewed).toHaveBeenCalledOnce()
        expect(exactAction).toHaveBeenCalledOnce()
        expect(card).toHaveBeenCalledOnce()
        expect(otherAction).not.toHaveBeenCalled()
        expect(otherCard).not.toHaveBeenCalled()
    })

    it('applies the view change to the stored conversation record', async () => {
        startRunRegistry(null)
        const stored = conversation('conversation-1', false)
        agentAcknowledgementService.connectConversationStore(() => stored)

        await agentAcknowledgementService.setViewed(cardInternalId, actionId, conversation('conversation-1', false), true)

        expect(stored.viewed).toBe(true)
        expect(hasUnseenConversation([stored])).toBe(false)
    })

    it('selects the newest unseen conversation and leaves older ones unseen', async () => {
        startRunRegistry(null)
        const older = conversation('older', false)
        const newest = conversation('newest', false)
        agentAcknowledgementService.connectConversationStore(() => newest)

        await agentAcknowledgementService.setViewed(cardInternalId, actionId, newest, true)

        expect(latestUnseenConversation([newest, older], actionId)).toEqual(older)
        expect(hasUnseenConversation([newest, older])).toBe(true)
    })

    it.each<ActionRunStatus>(['waitingForInput', 'completed', 'failed'])(
        'marks conversation unseen on transition into %s once',
        async (status) => {
            const running = conversation()
            const { publish, updateActionConversationViewed } = startRunRegistry(running)
            publish(runEvent('running'))
            publish(runEvent(status))
            publish(runEvent(status))

            await vi.waitFor(() => expect(updateActionConversationViewed).toHaveBeenCalledOnce())
            expect(updateActionConversationViewed).toHaveBeenCalledWith(running.path, false)
        },
    )

    it('marks conversation unseen again when it returns to a qualifying state', async () => {
        const running = conversation()
        const { publish, updateActionConversationViewed } = startRunRegistry(running)
        agentAcknowledgementService.connectConversationStore(() => running)
        publish(runEvent('waitingForInput'))
        await vi.waitFor(() => expect(running.viewed).toBe(false))

        await agentAcknowledgementService.setViewed(cardInternalId, actionId, running, true)
        publish(runEvent('running'))
        publish(runEvent('waitingForInput'))

        await vi.waitFor(() => expect(running.viewed).toBe(false))
        expect(updateActionConversationViewed).toHaveBeenCalledTimes(3)
        expect(updateActionConversationViewed).toHaveBeenLastCalledWith(running.path, false)
    })

    it.each<ActionRunStatus>(['queued', 'running', 'cancelled', 'okButNotAfter'])(
        'does not mark conversation unseen on transition into %s',
        (status) => {
            const { publish, updateActionConversationViewed } = startRunRegistry(conversation())
            publish(runEvent(status))

            expect(updateActionConversationViewed).not.toHaveBeenCalled()
        },
    )

    it('keeps a visible conversation viewed during a qualifying transition', () => {
        const running = conversation()
        const { publish, updateActionConversationViewed } = startRunRegistry(running)
        agentAcknowledgementService.setConversationVisible('popup-1', cardInternalId, actionId, running, true)

        publish(runEvent('running'))
        publish(runEvent('completed'))

        expect(updateActionConversationViewed).not.toHaveBeenCalled()
    })

    it('acknowledges an unseen conversation when its chat becomes visible', async () => {
        const { updateActionConversationViewed } = startRunRegistry(null)
        const unseen = conversation('conversation-1', false)

        agentAcknowledgementService.setConversationVisible('popup-1', cardInternalId, actionId, unseen, true)

        await vi.waitFor(() => expect(updateActionConversationViewed).toHaveBeenCalledWith(unseen.path, true))
        await vi.waitFor(() => expect(unseen.viewed).toBe(true))
    })

    it('leaves the conversation unseen and retryable when persistence fails', async () => {
        const error = new Error('disk failed')
        const updateActionConversationViewed = vi.fn()
            .mockRejectedValueOnce(error)
            .mockImplementation(async (reference: string, viewed: boolean) => ({ ...conversation(), path: reference, viewed }))
        setActionBridgeOverride({
            onActionRun: vi.fn(() => vi.fn()),
            updateActionConversationViewed,
        } as unknown as ElectronActionBridge)
        actionRunRegistry.start()
        const unseen = conversation('conversation-1', false)

        await expect(agentAcknowledgementService.setViewed(cardInternalId, actionId, unseen, true)).rejects.toThrow('disk failed')
        expect(unseen.viewed).toBe(false)

        await agentAcknowledgementService.setViewed(cardInternalId, actionId, unseen, true)
        expect(unseen.viewed).toBe(true)
        expect(updateActionConversationViewed).toHaveBeenCalledTimes(2)
    })

    it('ignores transitions without a card conversation identity', () => {
        const { publish, updateActionConversationViewed } = startRunRegistry(null)

        publish(runEvent('completed'))

        expect(updateActionConversationViewed).not.toHaveBeenCalled()
    })

    it('clears chat visibility at a project boundary', () => {
        const running = conversation()
        const { publish, updateActionConversationViewed } = startRunRegistry(running)
        agentAcknowledgementService.setConversationVisible('popup-1', cardInternalId, actionId, running, true)

        agentAcknowledgementService.reset()
        publish(runEvent('completed'))

        expect(updateActionConversationViewed).toHaveBeenCalledWith(running.path, false)
    })
})

const { resolveAgentCommand } = require('../actions/agent/agent_profiles.mjs');

const INTEGRATION_ACTIVITY_LABEL = 'Integrate into project';
const SEARCH_AGENT_PROMPT_PREFIX = 'Return only a single JavaScript-compatible regular expression pattern (no explanation, no surrounding text or markdown) that matches the following search request:\n\n';

function watchErrorMessage(error) {
    return error instanceof Error ? error.message : String(error);
}

function cardIntegrationTracking(request) {
    const hasCardInternalId = Object.hasOwn(request, 'cardInternalId');
    const hasProjectFolder = Object.hasOwn(request, 'projectFolder');
    if (!hasCardInternalId && !hasProjectFolder) return null;
    if (typeof request.cardInternalId !== 'string' || request.cardInternalId.length === 0) {
        throw new Error('Missing worktree integration cardInternalId');
    }
    if (typeof request.projectFolder !== 'string') throw new Error('Missing worktree integration projectFolder');

    return { cardInternalId: request.cardInternalId, projectFolder: request.projectFolder };
}

function worktreeIntegrationMetadata(request) {
    const tracking = cardIntegrationTracking(request);
    const deleteBranch = request.deleteBranch === true;
    if (request.deleteBranch !== undefined && typeof request.deleteBranch !== 'boolean') {
        throw new Error('Invalid worktree integration deleteBranch value');
    }
    if (deleteBranch && (typeof request.branchName !== 'string' || request.branchName.length === 0)) {
        throw new Error('Missing worktree integration branchName');
    }

    return { ...(tracking ?? {}), branchName: request.branchName ?? null, deleteBranch };
}

function errorMessage(error) {
    return error instanceof Error ? error.message : String(error);
}

function resolveSearchAgent(config) {
    const resolved = resolveAgentCommand(config);

    return {
        agent: resolved.agent,
        command: resolved.command,
    };
}

function createLocalBridgeDispatch(dependencies) {
    const {
        actionRunnerService,
        actionSchedulerService,
        agentExecutableAvailability,
        agentRunnerService,
        claudeRuntimeService,
        codexRuntimeService,
        desktopConfigStore,
        diffService,
        localGitService,
        mergeConflictService,
        openProjectFolder,
        openWorktreeFolder,
        readDesktopConfig,
        saveDesktopConfig,
        updateCodexCli,
        worktreeService,
    } = dependencies;
    let currentLocalProject = null;

    function isCurrentProject(project) {
        return !!currentLocalProject
            && currentLocalProject.branch === project.branch
            && currentLocalProject.id === project.id
            && currentLocalProject.rootPath === project.rootPath;
    }

    async function activateProject(project) {
        if (isCurrentProject(project)) return;

        const conflictSession = mergeConflictService?.getInternalSession();
        const sameConflictProject = conflictSession
            && conflictSession.projectBranch === project.branch
            && conflictSession.projectRoot === project.rootPath;
        if (conflictSession && !sameConflictProject) {
            if (!currentLocalProject || currentLocalProject.rootPath !== conflictSession.projectRoot) {
                const conflictProject = {
                    branch: conflictSession.projectBranch,
                    id: conflictSession.projectId,
                    rootPath: conflictSession.projectRoot,
                };
                await worktreeService.startProject(conflictProject);
            }
            await worktreeService.abortConflict({ sessionId: conflictSession.id });
        }

        currentLocalProject = project;
        if (actionSchedulerService) await actionSchedulerService.startProject(project);
        await worktreeService.startProject(project);
    }

    const dataBridge = {
        checkoutBranch: async (project, branch) => {
            const checkedOutProject = await localGitService.checkoutBranch(project, branch);
            await activateProject(checkedOutProject);

            return currentLocalProject;
        },
        cancelActionSchedule: (project, actionsFolder, scheduleId) => {
            if (actionSchedulerService) return actionSchedulerService.cancelActionSchedule(scheduleId);

            return localGitService.cancelActionSchedule(project, actionsFolder, scheduleId);
        },
        commit: async (request) => {
            await localGitService.commit(request, currentLocalProject);

            return [];
        },
        createProject: async (project, workingFolder) => {
            const createdProject = await localGitService.createProject(project, workingFolder);
            await activateProject(createdProject);

            return currentLocalProject;
        },
        deleteFile: (request) => localGitService.deleteFile(request, currentLocalProject),
        deleteFolder: (request) => localGitService.deleteFolder(request, currentLocalProject),
        getActiveProject: () => currentLocalProject,
        hasPendingPush: (project) => localGitService.hasPendingPush(project),
        listBranches: (project) => localGitService.listBranches(project),
        listAgentConversationReferences: (project, projectFolder) => (
            localGitService.listAgentConversationReferences(project, projectFolder)
        ),
        listRepositoryFiles: (project) => localGitService.listRepositoryFiles(project),
        listTopLevelFolders: (project) => localGitService.listTopLevelFolders(project),
        loadActionFiles: (project, actionsFolder) => localGitService.loadActionFiles(project, actionsFolder),
        loadActionSchedules: (project, actionsFolder) => localGitService.loadActionSchedules(project, actionsFolder),
        loadAgentConversation: async (reference) => {
            return localGitService.loadAgentConversation(currentLocalProject, reference);
        },
        loadAgentAvailability: () => {
            const { agentProfiles } = readDesktopConfig(desktopConfigStore);

            return agentExecutableAvailability(agentProfiles);
        },
        loadDesktopConfig: () => readDesktopConfig(desktopConfigStore),
        loadFile: (project, path) => localGitService.loadFile(project, path),
        loadTextFile: (project, path) => localGitService.loadTextFile(project, path),
        loadProjectAsset: (project, path) => localGitService.loadProjectAsset(project, path),
        loadProject: async (project, workingFolder) => {
            await activateProject(project);

            return localGitService.loadProject(project, workingFolder);
        },
        loadProjectConfig: (project) => localGitService.loadProjectConfig(project),
        loadProjectRoot: async (project, workingFolder) => {
            await activateProject(project);

            return localGitService.loadProjectRoot(project, workingFolder);
        },
        moveFiles: (request) => localGitService.moveFiles(request, currentLocalProject),
        openProjectFolder: async () => {
            if (!openProjectFolder) throw new Error('Project folder picker is not available');

            const rootPath = await openProjectFolder();
            if (!rootPath) return null;

            const project = await localGitService.resolveLocalProject(rootPath);
            await activateProject(project);

            return project;
        },
        addWorktree: (project, folderPath) => worktreeService.add(project, folderPath),
        prepareWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree preparation request');

            return worktreeService.prepare(request.project, request.worktree, request.branchName);
        },
        commitWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree commit request');

            return worktreeService.commit(request.project, request.worktree, request.message);
        },
        discardWorktreeChanges: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree discard request');

            return worktreeService.discard(request.project, request.worktree);
        },
        deleteLocalBranch: (project, branchName) => worktreeService.deleteBranch(project, branchName),
        integrateWorktree: async (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree integration request');
            const metadata = worktreeIntegrationMetadata(request);
            const integration = await worktreeService.integrate(request.project, request.worktree, metadata);
            if (integration.status === 'conflict') return integration;

            await finalizeIntegration(request.project, request.worktree, integration, metadata, false);

            return { status: 'completed' };
        },
        abortMergeConflict: (request) => worktreeService.abortConflict(request),
        continueMergeConflict: async (request) => {
